insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('pip','Pip',220,'Tiny keeper of tenderness. Proximity induces unexpected comfort; scholars remain blissfully baffled. Each totem is made to order; please allow up to two weeks for us to make Pip for you.','{"Solid bronze; Ombré patina","29 x 27 x 17 mm"}','perennial','live',null,0)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('rebi','Rebi',220,'Exhibits fluid properties, perceived silhouette in flux. Researchers report heightened reflexes after handling. Each totem is made to order; please allow up to two weeks for us to make Rebi for you.','{"Solid bronze; Ombré patina","42 x 16 x 16 mm"}','perennial','live',null,1)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('ren','Ren',220,'Steward of forgotten paths. Dawn light lingers unusually long upon golden mane. Each totem is made to order; please allow up to two weeks for us to make Ren for you.','{"Solid bronze; Ombré patina","40 x 37 x 13 mm"}','perennial','live',null,2)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('zuma','Zuma',220,'Desert spirit present. Namesake ring awakens dormant essence; ancient runes suggest sacred link. Each totem is made to order; please allow up to two weeks for us to make Zuma for you.','{"Solid bronze; Ombré patina","38 x 25 x 13 mm"}','perennial','live',null,3)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('ori','Ori',220,'Faithful guardian of the forests and rivers. Subtle warmth radiates during winter solstice. Each totem is made to order; please allow up to two weeks for us to make Ori for you.','{"Solid bronze; Ombré patina","35 x 21 x 19 mm"}','perennial','live',null,4)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('yael','Yaël',220,'Inimitable poise suggests prophecy in metal. Mountaintop altar bells resonate in its presence. Each totem is made to order; please allow up to two weeks for us to make Yael for you.','{"Solid bronze; Ombré patina","30 x 22 x 11 mm"}','perennial','live',null,5)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('zuma-ring','Zuma Ring',320,'Sand spirit distilled to sacred heirloom. Unearthed glyphs show evidence of rituals with paired totem. Each piece is made to order; please allow up to two weeks for us to make your Zuma Ring.','{"100% Sterling silver"}','perennial','live',null,6)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('milo','Milo',220,'Ancient wanderer seeking home. Surface adapts to handler; bonds deepen with patina over time. Each totem is made to order; please allow up to two weeks for us to make Milo for you.','{"Solid bronze; Ombré patina","36 x 26 x 11 mm"}','perennial','live',null,7)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('eclipse-ring','Eclipse Ring',340,'Asymmetric ellipses locked in patient equilibrium. The space between holds questions only stars can answer. Each piece is made to order; please allow up to two weeks for us to make your Eclipse Ring.','{"100% Sterling silver"}','perennial','live',null,8)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('sietch-aperture','Sietch Ring',340,'Recovered from the wake of a passing comet. Aperture reveals oscillating presence of landscapes that do not appear on any map. Each piece is made to order; please allow up to two weeks for us to make your Sietch Ring for you.','{"100% Sterling silver"}','perennial','live',null,9)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('lunar-canyon-ring','Lunar Canyon',370,'Sundered artifact forged from the core of a distant moon. Social gatherings reportedly ebb and flow in time with wearer''s presence. Each piece is made to order; please allow up to two weeks for us to make your Lunar Canyon Ring.','{"100% Sterling silver"}','perennial','live',null,10)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('eleph','Eleph',220,'Breath suspended in solid bronze. Distant trumpeting reported by independent observers. Eleph is currently on preorder and will ship late April.','{"Solid bronze; Ombré patina","34 x 31 x 14 mm"}','perennial','live',null,11)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('wonderhorn-talisman','Ida''s Wonder Horn',390,'Spiral resonator reveals undiscovered chords. Lab equipment vibrates sympathetically; nearby children develop perfect pitch. Each piece is made to order; please allow up to two weeks for us to make your Ida''s Wonder Horn.','{"100% Sterling silver, 30\" Chain"}','perennial','live',null,12)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('macon-cap','Maçon Cap',50,'Tasteful cap adorned with mystic symbol. Offers modicum of solar protection.','{}','perennial','live',null,13)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('ibi','Ibi',220,'Eternal watcher believed to guard ancestral secrets. Attempts to transmit likeness met with lens fog. Ibi is currently on preorder and will ship late April.','{"Solid bronze; Ombré patina","37 x 26 x 12 mm"}','perennial','live',null,14)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('ear-cuff','Caldera Arc',260,'Perfect geometries betray cosmic provenance. Light fractures into otherworldy spectra across mirrored edge. Each piece is made to order; please allow up to two weeks for us to make your Caldera Arc.','{"100% Sterling silver"}','perennial','live',null,15)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('starshipkey-pendant','Starship Key',460,'Elegant device of stellar origin. Prolonged exposure known to cause wanderlust; researchers &quot;forget&quot; to return. Each piece is made to order; please allow up to two weeks for us to make your Starship Key for you.','{"100% Sterling silver, 30\" chain"}','perennial','live',null,16)
insert into public.store_products (slug,name,price,description,notes,collection,status,quantity,sort_order) values ('meridian-egg-ring','Meridian Egg',390,'Weight exceeds material expectations. Metaphyiscal analysis detects abyss gazing back. Each piece is made to order; please allow up to two weeks for us to make your Meridian Egg.','{"100% Sterling silver"}','perennial','live',null,17)
